                {
                    myObject[jproperty.Name] = ParseObjectAlternative(jproperty.Value);
                }
                else
                {
                    myObject[jproperty.Name] = ParseJpropertyObject(jproperty);
                }
            }
            return myObject;
        }
        else
        {

            return ParseSimpleObject(Document);
        }
    }
